UPDATE section_localizations
SET content_json = '{"eyebrow":"Sobre a GTRZ","title":"A FESTA TEM IDENTIDADE.","body1":"A GTRZ cria festas e experiências com personalidade própria para uma comunidade latina diversa. Na mesma pista convivem referências, ritmos e públicos da Colômbia, Argentina, Venezuela, Cuba, Brasil e muito mais.","body2":"Cada edição é pensada de ponta a ponta: conceito, música, direção visual, comunicação e operação. A ideia não é repetir uma fórmula, mas dar a cada noite uma razão real para existir.","note":"NÃO FAZEMOS FESTAS EM SÉRIE. CADA EDIÇÃO PRECISA DE CONCEITO, RITMO E PRESENÇA.","metric1Value":"COMUNIDADE LATINA REAL","metric1Label":"Públicos diversos, referências compartilhadas e uma pista feita para conectar pessoas.","metric2Value":"CURADORIA MUSICAL","metric2Label":"Reggaeton, salsa, merengue, bachata, funk e misturas urbanas entram conforme a energia de cada edição.","metric3Value":"PT + ES","metric3Label":"Português e espanhol convivem de forma natural antes, durante e depois do evento.","metric4Value":"DO CONCEITO À OPERAÇÃO","metric4Label":"Visual, entrada, line-up, ambientação e experiência são pensados como um todo."}'
WHERE section_id = 'home_about' AND locale = 'pt-BR';

UPDATE section_localizations
SET content_json = '{"eyebrow":"Sobre la GTRZ","title":"LA FIESTA TIENE IDENTIDAD.","body1":"GTRZ crea fiestas y experiencias con personalidad propia para una comunidad latina diversa. En la misma pista conviven referencias, ritmos y públicos de Colombia, Argentina, Venezuela, Cuba, Brasil y mucho más.","body2":"Cada edición se piensa de punta a punta: concepto, música, dirección visual, comunicación y operación. La idea no es repetir una fórmula, sino darle a cada noche una razón real para existir.","note":"NO HACEMOS FIESTAS EN SERIE. CADA EDICIÓN NECESITA CONCEPTO, RITMO Y PRESENCIA.","metric1Value":"COMUNIDAD LATINA REAL","metric1Label":"Públicos diversos, referencias compartidas y una pista hecha para conectar personas.","metric2Value":"CURADURÍA MUSICAL","metric2Label":"Reggaeton, salsa, merengue, bachata, funk y mezclas urbanas entran según la energía de cada edición.","metric3Value":"PT + ES","metric3Label":"Portugués y español conviven de forma natural antes, durante y después del evento.","metric4Value":"DEL CONCEPTO A LA OPERACIÓN","metric4Label":"Visual, ingreso, line-up, ambientación y experiencia se piensan como un todo."}'
WHERE section_id = 'home_about' AND locale = 'es';